import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { schemeSchema, type Scheme } from "./scheme.js";

export type SecureRemoteCommerceCheckoutData = {
  /** The Secure Remote Commerce checkout payload to process the payment with. */
  checkoutPayload?: string;
  /**
   * This is the unique identifier generated by SRC system to track and link SRC messages. Available
   * within the present checkout session (e.g. received in an earlier API response during the
   * present session).
   */
  correlationId?: string;
  /**
   * The [card verification
   * code](https://docs.adyen.com/get-started-with-adyen/payment-glossary/#card-security-code-cvc-cvv-cid).
   */
  cvc?: string;
  /**
   * A unique identifier that represents the token associated with a card enrolled. Required for
   * scheme 'mc'.
   */
  digitalCardId?: string;
  /** The Secure Remote Commerce scheme. */
  scheme?: Scheme;
  /**
   * A unique identifier that represents the token associated with a card enrolled. Required for
   * scheme 'visa'.
   */
  tokenReference?: string;
};

export const secureRemoteCommerceCheckoutDataSchema: Schema<SecureRemoteCommerceCheckoutData> =
  s.object<SecureRemoteCommerceCheckoutData>({
    checkoutPayload: s.optional(s.string()),
    correlationId: s.optional(s.string()),
    cvc: s.optional(s.string()),
    digitalCardId: s.optional(s.string()),
    scheme: s.optional(s.lazy(() => schemeSchema)),
    tokenReference: s.optional(s.string()),
  });
